        # **Set Bar Width & Positions**
        x = np.arange(len(tools))  # X locations for groups
        width = 0.3  # Bar width (adjusted for spacing)
    
        # **Create the Figure**
        fig, ax = plt.subplots(figsize=(3.1 * scale_factor, 2.3 * scale_factor))
    
        # **Plot Bars for Males & Females**
